 assert _m5_by_field['ai_base_url']['aliases'] == []; assert _m5_by_field['llm_encryption_keys']['aliases'] == []; assert _m5_by_field['ai_provider']['aliases'] == []; assert _m5_by_field['debug']['aliases'] == []; assert tool_shim.main is gen.main; _m6_keys = gen.env_example_documented_keys('# === AI Provider ===\n# AI provider API key (empty key = AI features disabled).\n# Rotate = prepend a new key and re-encrypt.\n# ZAI_API_KEY=\nexport DEBUG=true\nDATABASE_URL = postgres://localhost/db\n'); assert _m6_keys == {'ZAI_API_KEY', 'DEBUG', 'DATABASE_URL'}
